                self.lifecycle_preference = None;
                row.failed = Some((code.clone(), message.clone()));
                self.lifecycle_strip = Some(format!("{code:?}: {message}"));
                self.provisional = Some(row);
                DashboardAction::Redraw
            }
        }
    }

